import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_boolean_function(n):
        return [random.choice([0, 1]) for _ in range(2**n)]

    def tensor_product_valuation(f1, f2):
        n = len(f1)
        m = len(f2)
        result = []
        for i in range(2**(n+m)):
            binary_rep = format(i, '0{}b'.format(n+m))
            x = int(binary_rep[:n], 2)
            y = int(binary_rep[n:], 2)
            result.append(f1[x] * f2[y])
        return result

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            if A[i][i] == 0:
                continue
            for j in range(n):
                A[i][j] /= A[i][i]
            for j in range(m):
                if j != i and A[j][i] != 0:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        rank = sum(1 for row in A if any(row))
        return rank

    def minimal_rank(f):
        n = int(math.log2(len(f)))
        valuations = [tensor_product_valuation(f, f) for _ in range(30)]
        ranks = [gaussian_elimination(valuation) for valuation in valuations]
        return min(ranks)

    n_values = [5, 10, 15, 20, 30, 40]
    total_rank = 0
    instances_tested = 0

    for n in n_values:
        f = generate_boolean_function(n)
        rank = minimal_rank(f)
        total_rank += rank
        instances_tested += 1

    mean_rank = total_rank / instances_tested
    conjecture_holds = mean_rank <= 3 * (n**(2/3))

    return {
        "metric_name": "Minimal Rank",
        "metric_value": mean_rank,
        "instances_tested": instances_tested,
        "conjecture_holds": conjecture_holds,
        "counterexample": ""
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [2**i + 1 for i in range(5, 30)]

    results = []
